func scan(path string,fn func(int,map[string]any)){f,e:=os.Open(path);if e!=nil{panic(e)};defer f.Close();s:=bufio.NewScanner(f);s.Buffer(make([]byte,65536),100*1024*1024);n:=0;for s.Scan(){n++;m:=map[string]any{};if json.Unmarshal(s.Bytes(),&m)==nil{fn(n,m)}};if e=s.Err();e!=nil{panic(e)}}
